<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }

function kimpu_register_spacing_controls( $customizer ) {
	$section = 'kimpu_design_spacing'; $customizer->add_section( $section, array( 'title' => __( 'Spacing & Borders', 'kimpu-multipurpose' ), 'panel' => 'kimpu_global_design', 'priority' => 60 ) );
	$fields = array( 'section_spacing' => array( 88, 32, 180, __( 'Section Vertical Spacing (px)', 'kimpu-multipurpose' ) ), 'container_padding_desktop' => array( 20, 10, 80, __( 'Desktop Container Padding (px)', 'kimpu-multipurpose' ) ), 'container_padding_tablet' => array( 24, 10, 60, __( 'Tablet Container Padding (px)', 'kimpu-multipurpose' ) ), 'container_padding_mobile' => array( 15, 10, 40, __( 'Mobile Container Padding (px)', 'kimpu-multipurpose' ) ), 'card_padding' => array( 24, 8, 60, __( 'Card Padding (px)', 'kimpu-multipurpose' ) ), 'grid_gap' => array( 22, 8, 60, __( 'Grid Gap (px)', 'kimpu-multipurpose' ) ), 'radius_small' => array( 6, 0, 30, __( 'Small Radius (px)', 'kimpu-multipurpose' ) ), 'radius_medium' => array( 10, 0, 40, __( 'Medium Radius (px)', 'kimpu-multipurpose' ) ), 'radius_large' => array( 16, 0, 60, __( 'Large Radius (px)', 'kimpu-multipurpose' ) ), 'card_radius' => array( 12, 0, 40, __( 'Card Radius (px)', 'kimpu-multipurpose' ) ) );
	foreach ( $fields as $key => $data ) { $id = 'kimpu_design_' . $key; $customizer->add_setting( $id, array( 'default' => $data[0], 'sanitize_callback' => function( $v ) use ( $data ) { return (int) kimpu_sanitize_design_number( $v, $data[1], $data[2] ); }, 'transport' => 'postMessage' ) ); $customizer->add_control( $id, array( 'label' => $data[3], 'section' => $section, 'type' => 'number', 'input_attrs' => array( 'min' => $data[1], 'max' => $data[2] ) ) ); }
	$customizer->add_setting( 'kimpu_design_shadow_style', array( 'default' => 'subtle', 'sanitize_callback' => function( $v ) { return kimpu_sanitize_design_choice( $v, array( 'none', 'subtle', 'medium', 'elevated' ), 'subtle' ); }, 'transport' => 'postMessage' ) ); $customizer->add_control( 'kimpu_design_shadow_style', array( 'label' => __( 'Shadow Style', 'kimpu-multipurpose' ), 'section' => $section, 'type' => 'select', 'choices' => array( 'none' => __( 'None', 'kimpu-multipurpose' ), 'subtle' => __( 'Subtle', 'kimpu-multipurpose' ), 'medium' => __( 'Medium', 'kimpu-multipurpose' ), 'elevated' => __( 'Elevated', 'kimpu-multipurpose' ) ) ) );
	$customizer->add_setting( 'kimpu_design_spacing_preset', array( 'default' => 'comfortable', 'sanitize_callback' => function( $v ) { return kimpu_sanitize_design_choice( $v, array( 'compact', 'comfortable', 'spacious' ), 'comfortable' ); }, 'transport' => 'refresh' ) ); $customizer->add_control( 'kimpu_design_spacing_preset', array( 'label' => __( 'Spacing Preset', 'kimpu-multipurpose' ), 'section' => $section, 'type' => 'select', 'choices' => array( 'compact' => __( 'Compact', 'kimpu-multipurpose' ), 'comfortable' => __( 'Comfortable', 'kimpu-multipurpose' ), 'spacious' => __( 'Spacious', 'kimpu-multipurpose' ) ) ) );
}
